import {localDate,habitEntry,habitDue,habitDone,habitStreak} from './domain.js';
const colors=['#f66c72','#ff963d','#ffc52c','#f5d514','#a4dc36','#45d881','#2bc69a','#27cbbb','#21c7df','#35b9eb','#609ff3','#8886f4','#a38bf4','#bf85f3','#dd7bed','#ed77b6','#f56b8b','#94a3b8','#9ca3af','#a3a3a3','#aaa29b'];
const symbols={pulse:'<path d="M2 12h5l3-8 4 16 3-8h5"/>',book:'<path d="M12 6v15M3 4l9 2 9-2v15l-9 2-9-2z"/>',water:'<path d="M12 2S4 11 4 15a8 8 0 0 0 16 0C20 11 12 2 12 2z"/>',moon:'<path d="M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',leaf:'<path d="M20 3C4 1 1 16 8 18S22 15 20 3ZM4 21 15 9"/>',heart:'<path d="M12 21 3 12C-2 4 7 0 12 7c5-7 14-3 9 5z"/>',coffee:'<path d="M3 4h13v11a5 5 0 0 1-5 5H8a5 5 0 0 1-5-5zM16 6h2a4 4 0 0 1 0 8h-2M2 23h17"/>',focus:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>'};
const symbolNames={pulse:'Aktivität',book:'Lesen',water:'Wasser',moon:'Schlaf',sun:'Morgen',leaf:'Natur',heart:'Gesundheit',coffee:'Kaffee',focus:'Fokus'};
const glyph=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${symbols[n]||symbols.pulse}</svg>`;
const shift=(date,offset)=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+offset);return localDate(d);};
const days=['Mo','Di','Mi','Do','Fr','Sa','So'];
export function createHabits(c){
 const {esc,icon}=c;let mode='cards',filter='',showArchived=false,detail=null,month=localDate().slice(0,7),draft=null;
 const state=()=>c.getState();const all=()=>state().habits||[];const entry=(h,d)=>habitEntry(state(),h.id,d);const done=(h,d)=>habitDone(h,entry(h,d));
 const attr=h=>`style="--habit-color:${h.color}"`;
 const action=(a,id,extra='')=>`data-action="habit-${a}" data-id="${id}" ${extra}`;
 const tiny=(h,d)=>`<button class="heat-cell ${done(h,d)?'filled':''} ${habitDue(h,d)?'':'unscheduled'} ${d===localDate()?'heat-today':''}" ${action('log',h.id,`data-date="${d}"`)} ${d>localDate()||d<h.createdDate?'disabled':''} aria-label="${esc(h.name)}, ${d}${done(h,d)?', erledigt':''}" title="${d}${done(h,d)?' · Erledigt':''}"></button>`;
 function heatmap(h){const today=localDate(),monday=shift(today,-((new Date(today+'T12:00:00').getDay()+6)%7));const start=shift(monday,-175);return `<div class="habit-heatmap" aria-label="Letzte 26 Wochen">${Array.from({length:182},(_,i)=>tiny(h,shift(start,i))).join('')}</div>`;}
 function quick(h){const d=localDate(),e=entry(h,d);return `<button class="habit-check ${done(h,d)?'completed':''}" ${action('quick',h.id)} aria-label="${esc(h.name)}: ${h.tracking==='boolean'?(done(h,d)?'Häkchen entfernen':'Heute abhaken'):'Wert eintragen'}">${done(h,d)?icon('check'):h.tracking==='boolean'?icon('plus'):`<span class="habit-ring" style="--progress:${Math.min(100,(e?.value||0)/h.target*100)}%">${icon('plus')}</span>`}</button>`;}
 function card(h){return `<article class="habit-card" ${attr(h)}><div class="habit-card-top"><button class="habit-name" ${action('detail',h.id)}><span class="habit-symbol">${glyph(h.icon)}</span><span><strong>${esc(h.name)}</strong><small>${esc(h.category|| (h.kind==='quit'?'Abgewöhnen':'Aufbauen'))}</small></span></button>${quick(h)}</div>${heatmap(h)}<div class="habit-card-foot"><span>${habitStreak(h,state().habitEntries)} Tage Serie</span><span>${h.tracking==='boolean'?(done(h,localDate())?'Heute erledigt':'Heute offen'):`${entry(h,localDate())?.value||0} / ${h.target} ${esc(h.unit)}`}</span></div></article>`;}
 function table(list){const dates=Array.from({length:5},(_,i)=>shift(localDate(),i-4));return `<div class="habit-table"><div class="habit-table-row habit-table-head"><span>${list.length} Gewohnheiten</span>${dates.map(d=>`<span>${days[(new Date(d+'T12:00:00').getDay()+6)%7]}<b>${Number(d.slice(-2))}</b></span>`).join('')}</div>${list.map(h=>`<div class="habit-table-row" ${attr(h)}><button class="habit-name" ${action('detail',h.id)}><span class="habit-symbol">${glyph(h.icon)}</span><strong>${esc(h.name)}</strong></button>${dates.map(d=>`<button class="habit-day-check ${done(h,d)?'completed':''}" ${action('log',h.id,`data-date="${d}"`)} ${d<h.createdDate?'disabled':''} aria-label="${esc(h.name)}, ${d}">${done(h,d)?icon('check'):''}</button>`).join('')}</div>`).join('')}</div>`;}
 function stats(list){const dates=Array.from({length:30},(_,i)=>shift(localDate(),i-29));return `<div class="habit-stats-grid">${list.map(h=>{const scheduled=dates.filter(d=>habitDue(h,d)),completed=scheduled.filter(d=>done(h,d));return `<article class="habit-card" ${attr(h)}><button class="habit-name" ${action('detail',h.id)}><span class="habit-symbol">${glyph(h.icon)}</span><strong>${esc(h.name)}</strong></button><div class="habit-big-number">${scheduled.length?Math.round(completed.length/scheduled.length*100):0}<small>%</small></div><p class="muted">${completed.length} von ${scheduled.length} geplanten Tagen · letzte 30 Tage</p><div class="habit-stat-bar"><i style="width:${scheduled.length?completed.length/scheduled.length*100:0}%"></i></div><p>${habitStreak(h,state().habitEntries)} Tage aktuelle Serie${h.streakGoal?` · Ziel ${h.streakGoal}`:''}</p></article>`;}).join('')}</div>`;}
 function render(){
  if(detail){const h=all().find(h=>h.id===detail);if(h)return detailView(h);detail=null;}
  const categories=[...new Set(all().filter(h=>!h.archived).map(h=>h.category).filter(Boolean))].sort();const list=all().filter(h=>h.archived===showArchived&&(!filter||h.category===filter));
  return `<section class="habits-section"><div class="habit-toolbar"><div class="habit-tabs" aria-label="Gewohnheiten filtern"><button ${action('archive-view','')} aria-pressed="${showArchived}">${showArchived?'Archiv':'Aktiv'} ${icon('back')}</button><select id="habit-category-filter" aria-label="Kategorie"><option value="">Alle Kategorien</option>${categories.map(v=>`<option ${filter===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div><button class="habit-add" ${action('new','')} aria-label="Neue Gewohnheit">${icon('plus')}</button></div>${list.length?`<div class="habit-overview-label"><span>${mode==='table'?'Letzte 5 Tage':mode==='stats'?'Deine Konstanz':'Letzte 26 Wochen'}</span><span>${list.length} Gewohnheiten</span></div>${mode==='table'?table(list):mode==='stats'?stats(list):`<div class="habit-cards">${list.map(card).join('')}</div>`}`:`<div class="habit-empty"><span class="habit-symbol">${glyph('pulse')}</span><h2>${showArchived?'Dein Archiv ist leer.':'Deine erste Gewohnheit.'}</h2><p>Wähle, was du aufbauen oder abgewöhnen möchtest.</p><button class="primary-button" ${action('new','')}>Gewohnheit erstellen ${icon('plus')}</button></div>`}<nav class="habit-view-switch" aria-label="Habit-Ansicht">${[['cards','grid','Karten'],['table','check','Tage'],['stats','chart','Statistik']].map(([m,i,l])=>`<button class="${mode===m?'active':''}" ${action('mode',m)} aria-label="${l}" aria-pressed="${mode===m}">${icon(i)}</button>`).join('')}</nav></section>`;
 }
 function detailView(h){const first=new Date(month+'-01T12:00:00'),start=shift(localDate(first),-((first.getDay()+6)%7));const notes=(state().habitEntries||[]).filter(e=>e.habitId===h.id&&e.note).sort((a,b)=>b.date.localeCompare(a.date));return `<section class="habits-section habit-detail" ${attr(h)}><div class="habit-detail-header"><button class="icon-button" ${action('back','')} aria-label="Zurück">${icon('back')}</button><div class="habit-symbol">${glyph(h.icon)}</div><div class="habit-detail-title"><h2>${esc(h.name)}</h2><p>${esc(h.description||'Keine Beschreibung')}</p></div><button class="icon-button" ${action('edit',h.id)} aria-label="Gewohnheit bearbeiten">${icon('settings')}</button></div><div class="habit-card">${heatmap(h)}</div><div class="habit-pills"><span>${habitStreak(h,state().habitEntries)} Tage Serie</span><span>${h.streakGoal?`Ziel: ${h.streakGoal} Tage`:'Kein Serienziel'}</span>${h.archived?'<span>Archiviert</span>':''}</div><div class="habit-month"><div class="habit-calendar">${days.map(d=>`<span class="habit-weekday">${d}</span>`).join('')}${Array.from({length:42},(_,i)=>{const d=shift(start,i);return `<button class="habit-calendar-day ${d.slice(0,7)!==month?'outside':''} ${done(h,d)?'completed':''} ${d===localDate()?'today':''}" ${action('log',h.id,`data-date="${d}"`)} ${d>localDate()||d<h.createdDate?'disabled':''} aria-label="${d}${done(h,d)?', erledigt':''}">${Number(d.slice(-2))}${entry(h,d)?.note?'<i></i>':''}</button>`;}).join('')}</div><div class="habit-month-controls"><label><span class="sr-only">Monat</span><input id="habit-month" type="month" value="${month}" max="${localDate().slice(0,7)}"></label><button ${action('today','')}>Heute</button><button ${action('month','-1')} aria-label="Vorheriger Monat">${icon('back')}</button><button ${action('month','1')} ${month>=localDate().slice(0,7)?'disabled':''} aria-label="Nächster Monat"><span class="flip">${icon('back')}</span></button></div><p class="muted">Tippe auf einen Tag, um Wert oder Notiz zu bearbeiten.</p></div><section class="habit-notes"><h3>Notizen</h3>${notes.length?notes.map(e=>`<button ${action('log',h.id,`data-date="${e.date}"`)}><small>${e.date}</small><p>${esc(e.note)}</p></button>`).join(''):'<p class="muted">Noch keine Notizen.</p>'}</section></section>`;}
 function editor(h){draft=structuredClone(h||{id:crypto.randomUUID(),name:'',description:'',color:colors[0],icon:'pulse',kind:'build',tracking:'boolean',target:1,unit:'',category:'',days:[0,1,2,3,4,5,6],streakGoal:0,archived:false,createdDate:localDate(),updatedAt:new Date().toISOString()});editorView();}
 function editorView(){const h=draft;c.openDialog(`<div class="habit-editor" ${attr(h)}><h2>${all().some(x=>x.id===h.id)?'Gewohnheit bearbeiten':'Neue Gewohnheit'}</h2><div class="habit-icon-preview"><span class="habit-symbol">${glyph(h.icon)}</span></div><div class="habit-icon-choices" aria-label="Icon wählen">${Object.keys(symbols).map(k=>`<button class="${h.icon===k?'selected':''}" ${action('symbol',k)} aria-label="${symbolNames[k]}" aria-pressed="${h.icon===k}">${glyph(k)}</button>`).join('')}</div><label>Name<input id="habit-name" maxlength="60" value="${esc(h.name)}" placeholder="Zum Beispiel Lesen" required></label><label>Beschreibung<textarea id="habit-description" maxlength="500" rows="2">${esc(h.description)}</textarea></label><div class="habit-field-label">Farbe</div><div class="habit-colors">${colors.map((v,i)=>`<button style="--swatch:${v}" class="${h.color===v?'selected':''}" ${action('color',v)} aria-label="Farbe ${i+1}" aria-pressed="${h.color===v}"></button>`).join('')}</div><div class="habit-field-label">Art der Gewohnheit</div><div class="habit-segments">${[['build','Aufbauen'],['quit','Abgewöhnen']].map(([v,l])=>`<button ${action('kind',v)} aria-pressed="${h.kind===v}">${l}</button>`).join('')}</div><p class="habit-help">${h.kind==='quit'?'Markiere die Tage, an denen du bewusst darauf verzichtet hast.':'Markiere die Tage, an denen du dein Ziel erreichst.'}</p><div class="habit-field-label">Erfassung</div><div class="habit-segments">${[['boolean','Ja / Nein'],['counter','Zähler'],['measure','Messwert']].map(([v,l])=>`<button ${action('tracking',v)} aria-pressed="${h.tracking===v}">${l}</button>`).join('')}</div>${h.tracking!=='boolean'?`<div class="habit-form-columns"><label>Tagesziel<input id="habit-target" type="number" min="0.01" max="1000000" step="${h.tracking==='counter'?'1':'any'}" value="${h.target}"></label><label>Einheit<input id="habit-unit" maxlength="20" placeholder="${h.tracking==='counter'?'Mal':'Minuten'}" value="${esc(h.unit)}"></label></div>`:''}<div class="habit-field-label">Geplante Tage</div><div class="habit-day-options">${days.map((d,i)=>`<button ${action('weekday',i)} aria-pressed="${h.days.includes(i)}">${d}</button>`).join('')}</div><div class="habit-form-columns"><label>Serienziel (Tage)<input id="habit-streak" type="number" min="0" max="10000" step="1" value="${h.streakGoal}" placeholder="0 = keines"></label><label>Kategorie<input id="habit-category" maxlength="40" value="${esc(h.category)}" placeholder="Zum Beispiel Alltag"></label></div><button class="primary-button full-width" ${action('save',h.id)}>Speichern ${icon('check')}</button>${all().some(x=>x.id===h.id)?`<div class="habit-editor-actions"><button class="text-button" ${action('archive',h.id)}>${h.archived?'Wieder aktivieren':'Archivieren'}</button><button class="text-button danger" ${action('delete',h.id)}>Löschen</button></div>`:''}</div>`,'Gewohnheit');}
 function readDraft(){if(!draft)return;for(const [field,id] of Object.entries({name:'name',description:'description',target:'target',unit:'unit',streakGoal:'streak',category:'category'})){const el=document.getElementById('habit-'+id);if(el)draft[field]=['target','streakGoal'].includes(field)?Number(el.value):el.value.trim();}}
 function log(h,date){if(date>localDate()||date<h.createdDate)return;const e=entry(h,date);c.openDialog(`<div class="habit-editor" ${attr(h)}><div class="eyebrow">${date}</div><h2>${esc(h.name)}</h2>${h.tracking==='boolean'?`<label class="habit-log-toggle"><input id="habit-log-done" type="checkbox" ${done(h,date)?'checked':''}>${h.kind==='quit'?'Bewusst verzichtet':'Erledigt'}</label>`:`<label>${h.tracking==='counter'?'Anzahl':'Messwert'} ${esc(h.unit)}<input id="habit-log-value" type="number" min="0" max="1000000" step="${h.tracking==='counter'?'1':'any'}" value="${e?.value??0}"></label><p class="muted">Tagesziel: ${h.target} ${esc(h.unit)}</p>`}<label>Notiz<textarea id="habit-log-note" rows="3" maxlength="2000" placeholder="Wie lief dein Tag?">${esc(e?.note||'')}</textarea></label><button class="primary-button full-width" ${action('save-log',h.id,`data-date="${date}"`)}>Speichern ${icon('check')}</button></div>`,'Tag bearbeiten');}
 function put(h,date,value,note=''){const id=h.id+'-'+date;state().habitEntries||=[];state().habitEntries=state().habitEntries.filter(e=>e.id!==id);state().habitEntries.push({id,habitId:h.id,date,value,note,updatedAt:new Date().toISOString()});c.persist();}
 async function handle(a,b){if(!a.startsWith('habit-'))return false;const id=b.dataset.id,h=all().find(h=>h.id===id);switch(a.slice(6)){
 case 'new':editor();break;case 'edit':if(h)editor(h);break;case 'mode':mode=id;c.render();break;case 'archive-view':showArchived=!showArchived;filter='';c.render();break;case 'detail':detail=id;month=localDate().slice(0,7);c.render();window.scrollTo(0,0);break;case 'back':detail=null;c.render();break;
 case 'month':{const d=new Date(month+'-01T12:00:00');d.setMonth(d.getMonth()+Number(id));month=localDate(d).slice(0,7);c.render();break;}case 'today':month=localDate().slice(0,7);c.render();break;
 case 'quick':if(h){if(h.tracking==='boolean'){put(h,localDate(),done(h,localDate())?0:1,entry(h,localDate())?.note||'');c.render();}else if(h.tracking==='counter'){put(h,localDate(),Math.min(1000000,(entry(h,localDate())?.value||0)+1),entry(h,localDate())?.note||'');c.render();}else log(h,localDate());}break;
 case 'log':if(h)log(h,b.dataset.date);break;case 'save-log':if(h){const v=h.tracking==='boolean'?(document.getElementById('habit-log-done').checked?1:0):Number(document.getElementById('habit-log-value').value);if(!Number.isFinite(v)||v<0||v>1000000||(h.tracking==='counter'&&!Number.isInteger(v))){c.toast('Bitte einen gültigen Wert eintragen.');break;}put(h,b.dataset.date,v,document.getElementById('habit-log-note').value.trim());c.closeDialog();c.render();}break;
 case 'symbol':case 'color':case 'kind':case 'tracking':case 'weekday':readDraft();if(!draft)break;if(a==='habit-weekday'){const d=Number(id);draft.days=draft.days.includes(d)?draft.days.filter(x=>x!==d):[...draft.days,d];}else draft[a.slice(6)==='symbol'?'icon':a.slice(6)]=id;editorView();break;
 case 'save':readDraft();if(!draft?.name||!draft.days.length||!Number.isFinite(draft.target)||draft.target<=0||draft.target>1000000||(draft.tracking==='counter'&&!Number.isInteger(draft.target))||!Number.isInteger(draft.streakGoal)||draft.streakGoal<0||draft.streakGoal>10000){c.toast('Bitte Name, gültiges Ziel und mindestens einen Tag angeben.');break;}if(all().length>=200&&!h){c.toast('Maximal 200 Gewohnheiten.');break;}draft.updatedAt=new Date().toISOString();if(draft.tracking==='boolean')draft.target=1;state().habits=[...all().filter(x=>x.id!==draft.id),draft];if(c.persist()){draft=null;c.closeDialog();c.render();}break;
 case 'archive':if(h){h.archived=!h.archived;h.updatedAt=new Date().toISOString();c.persist();detail=null;c.closeDialog();c.render();}break;
 case 'delete':c.openDialog(`<h2>Gewohnheit löschen?</h2><p>Alle Einträge und Notizen dieser Gewohnheit werden gelöscht.</p><button class="primary-button full-width" ${action('confirm-delete',id)}>Endgültig löschen</button>`);break;
 case 'confirm-delete':if(h){const stamp=new Date().toISOString();state().deleted[id]=stamp;for(const e of state().habitEntries.filter(e=>e.habitId===id))state().deleted[e.id]=stamp;state().habits=all().filter(x=>x.id!==id);state().habitEntries=state().habitEntries.filter(e=>e.habitId!==id);c.persist();detail=null;c.closeDialog();c.render();}break;
 }return true;}
 function change(el){if(el.id==='habit-category-filter'){filter=el.value;c.render();}if(el.id==='habit-month'&&/^\d{4}-\d{2}$/.test(el.value)&&el.value<=localDate().slice(0,7)){month=el.value;c.render();}}
 return{render,handle,change};
}
